def flatten(xs, depth: int) -> list:
    result = []
    stack = [(xs, depth)]
    while stack:
        current, d = stack.pop()
        for item in reversed(current):
            if isinstance(item, list) and d > 0:
                stack.append((item, d - 1))
            else:
                result.append(item)
    return result
```

