def flatten(xs, depth: int) -> list:
    if depth <= 0:
        return list(xs)
    result = []
    for x in xs:
        if isinstance(x, list) and depth > 0:
            result.extend(flatten(x, depth - 1))
        else:
            result.append(x)
    return result
```

